template:
@php
    // Suggestions while typing (W6.5) against the showcase's door (GET webx/widgets/showcase/suggest),
    // which answers HTML the way a site's address of suggestions does. The goods and every word are
    // this block's localized fields, carried to the door in the address of the suggestions.
    // A search box: a GET search to this page, which lists what was found without JavaScript.
    // A field: inside another form, a value chosen fills it; the form is sent as it would be.
    $search = $mode !== 'field';
    $param = $search ? 'q' : 'city';
    $path = '/'.ltrim(request()->path(), '/');
    $source = route('webx-widgets.showcase.suggest', array_filter([
        'as' => $search ? null : 'values',
        'items' => (string) $goods,
        'to' => $path,
        'words' => ['products' => (string) $products_label, 'all' => (string) $all_label, 'nothing' => (string) $nothing_label],
    ]));
    $asked = request()->query($param);
    $asked = is_string($asked) ? trim($asked) : '';
    $found = $search && $asked !== ''
        ? \WebxUi\Widgets\Forms\ShowcaseController::found(\WebxUi\Widgets\Forms\ShowcaseController::items((string) $goods), $asked)
        : [];
@endphp
<section class="b-showcase-suggest" data-wx-block="showcase-suggest" data-mode="{{ $search ? 'search' : 'field' }}">
    @if ($heading)
        <h2 class="b-showcase-suggest__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-suggest__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-suggest__frame">
        @if ($search)
            <x-webx-suggest :action="$path" :source="$source" :value="$asked" :recent="5" :label="(string) $label"
                            :placeholder="(string) $placeholder" :submit-label="(string) $button" />
            @if ($asked !== '')
                <div class="b-showcase-suggest__results" role="status">
                    <p class="b-showcase-suggest__results-heading">{{ str_replace([':q', ':count'], [$asked, (string) count($found)], (string) $results_label) }}</p>
                    @if ($found === [])
                        <p class="b-showcase-suggest__nothing">{{ str_replace(':q', $asked, (string) $nothing_label) }}</p>
                    @else
                        <ul class="b-showcase-suggest__list">
                            @foreach ($found as $item)
                                <li class="b-showcase-suggest__item"><span class="b-showcase-suggest__card-name">{{ $item['name'] }}</span> <span class="b-showcase-suggest__card-price">{{ $item['price'] }}</span></li>
                            @endforeach
                        </ul>
                    @endif
                </div>
            @endif
        @else
            <x-webx-form method="get" :action="$path" class="b-showcase-suggest__form">
                <x-webx-suggest :source="$source" name="city" :value="$asked" :show-label="true" :label="(string) $label"
                                :placeholder="(string) $placeholder" />
                <x-webx-form.submit>{{ $button }}</x-webx-form.submit>
            </x-webx-form>
            @if ($asked !== '')
                <p class="b-showcase-suggest__chosen" role="status">{{ str_replace(':value', $asked, (string) $chosen_label) }}</p>
            @endif
        @endif
    </div>
</section>

styles:
.b-showcase-suggest {
    container-type: inline-size;
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-suggest__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-suggest__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-suggest__frame {
    max-width: 36rem;
}

.b-showcase-suggest__form {
    display: flex;
    flex-direction: column;
    gap: var(--site-space-3);
}

.b-showcase-suggest__found-heading {
    margin: 0;
    padding: var(--site-space-1) var(--site-space-3);
    color: var(--site-color-text-muted);
    font-size: var(--site-font-size-6);
    font-weight: 600;
}

.b-showcase-suggest__card-body {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: var(--site-space-1) var(--site-space-3);
}

.b-showcase-suggest__card-price {
    font-weight: 600;
    white-space: nowrap;
}

.b-showcase-suggest__mark {
    background: transparent;
    color: inherit;
    font-weight: 700;
    text-decoration: underline;
}

.b-showcase-suggest__all {
    font-weight: 600;
}

.b-showcase-suggest__values {
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-showcase-suggest__nothing {
    margin: 0;
    padding: var(--site-space-2) var(--site-space-3);
    color: var(--site-color-text-muted);
}

.b-showcase-suggest__results {
    margin-block-start: var(--site-space-5);
}

.b-showcase-suggest__results-heading {
    margin: 0 0 var(--site-space-2);
    font-weight: 600;
}

.b-showcase-suggest__list {
    display: grid;
    gap: var(--site-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-showcase-suggest__item {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: var(--site-space-3);
    padding: var(--site-space-2) var(--site-space-3);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
}

.b-showcase-suggest__chosen {
    margin: var(--site-space-4) 0 0;
    font-weight: 600;
}
